 dict(id='pango',n='Pango Point lighthouse',c='beach',lon=168.2596,lat=-17.7813,t='1 hour',d='The south-western tip of the Pango peninsula, with a lighthouse and sea views. A good end-of-day stop for the sunset side of the island.',tip='Combine with a swim at Pango Beach on the way.'),
 dict(id='hideaway',n='Hideaway Island Marine Sanctuary',c='sea',lon=168.2633,lat=-17.6965,t='Half a day',d='Just offshore from Mele Beach, one of Vila\'s favourite spots for snorkelling and diving. It is also home to the world\'s only underwater post office, so you can send a postcard from the sea.',tip='Bring your own snorkel and fins to save hire costs; postcards are sold on the island.'),
 dict(id='mele',n='Mele Cascades',c='water',lon=168.2594,lat=-17.6760,t='1.5–2 hours',d='A series of clear aquamarine pools beneath a 35-metre waterfall, about a half-hour drive from Port Vila. Walk up through the pools for the views from the top.',tip='Go first thing, before the cruise-ship crowds, and wear shoes you can get wet.'),
