 dict(id='eton',n='Eton Beach',c='beach',lon=168.5618,lat=-17.7382,t='1–2 hours',d='A brochure-style stretch of white sand with calm water, child-friendly rock pools and a freshwater stream feeding a lagoon, about a 40-minute drive from Port Vila.',tip='Entry goes to Eton Village to maintain the beach; camping is possible for a small fee.'),
