K={'hideaway':'Dive & snorkel','havannah':'Snorkel','milliondollar':'Dive & snorkel','coolidge':'Dive','lamenbay':'Snorkel','tranquillity':'Dive','lelepa':'Snorkel','ngunapele':'Snorkel','aorefan':'Dive','tutuba':'Dive & snorkel','uripiv':'Snorkel','erakor':'Snorkel','eton':'Snorkel','champagne':'Snorkel','mystery':'Snorkel'}
